pre_install:
if (!(is_admin)) { throw "$app requires admin rights to $cmd" }

$sourceInstaller = Join-Path $dir $fname
$downloadUrl = "https://a11.gdl.easebar.com/$fname"
$cachedInstaller = cache_path $app $version $downloadUrl
$transactionId = [guid]::NewGuid().ToString()
$stagingDir = $null
$mumuInstallCompleted = $false

try {
    $mumuMigrationHelperPath = Join-Path $env:TEMP ("mumuplayer-scoop-path-migration-{0}.ps1" -f $PID)
    $mumuMigrationHelperContent = @'
param(
    [Parameter(Mandatory=$true)][ValidateSet('Pre','Post')][string]$Phase,
    [Parameter(Mandatory=$true)][string]$VersionRoot,
    [Parameter(Mandatory=$true)][string]$PersistRoot,
    [string]$AppDataConfig,
    [string]$ProgramFilesRoot = $env:ProgramFiles,
    [string]$ServicesRegistryRoot = 'HKLM:\SYSTEM\CurrentControlSet\Services',
    [string]$ClassesRegistryRoot = 'HKLM:\SOFTWARE\Classes\CLSID'
)
$ErrorActionPreference = 'Stop'
$VersionRoot = [IO.Path]::GetFullPath($VersionRoot).TrimEnd('\')
$PersistRoot = [IO.Path]::GetFullPath($PersistRoot).TrimEnd('\')
$AppRoot = Split-Path -LiteralPath $VersionRoot -Parent
if ((Split-Path -LiteralPath $AppRoot -Leaf) -ine 'mumuplayer') { throw "Unexpected MuMu Scoop root: $AppRoot" }
if ((Split-Path -LiteralPath $VersionRoot -Leaf) -notmatch '^\d+(?:\.\d+)+$') { throw "Not a Scoop version directory: $VersionRoot" }
$script:AppRoot = $AppRoot
$script:VersionRoot = $VersionRoot
$script:PersistRoot = $PersistRoot
$script:Phase = $Phase
$script:Changed = [System.Collections.Generic.List[object]]::new()
$script:Unresolved = [System.Collections.Generic.List[string]]::new()

function Set-MuMuPaths {
    param([object]$Node,[string]$File,[string]$Key = '')
    if ($null -eq $Node) { return $null }
    if ($Node -is [System.Collections.IDictionary]) {
        foreach ($k in @($Node.Keys)) {
            $Node[$k] = Set-MuMuPaths -Node $Node[$k] -File $File -Key ([string]$k)
        }
        return $Node
    }
    if ($Node -is [System.Collections.IList]) {
        for ($i=0; $i -lt $Node.Count; $i++) {
            $Node[$i] = Set-MuMuPaths -Node $Node[$i] -File $File -Key $Key
        }
        return ,$Node
    }
    if ($Node -isnot [string] -or $Key -notmatch '^(?i:path|install_dir|.*_path|.*_dir)$') { return $Node }

    $tail = $null
    $sourceRoot = $null
    $appPattern = '^' + [regex]::Escape($script:AppRoot) + '\\(?<ver>current|_?\d+(?:\.\d+)+(?:\.old)?)(?<tail>\\.*)?$'
    $appMatch = [regex]::Match($Node,$appPattern,[System.Text.RegularExpressions.RegexOptions]::IgnoreCase)

    if ($appMatch.Success) {
        $tail = [string]$appMatch.Groups['tail'].Value
        $sourceRoot = 'ScoopVersion'
    } elseif ($script:Phase -eq 'Post') {
        $persistPattern = '^' + [regex]::Escape($script:PersistRoot) + '(?<tail>\\(?:configs|vms|nx_device)(?:\\.*)?)$'
        $persistMatch = [regex]::Match($Node,$persistPattern,[System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
        if ($persistMatch.Success) {
            $tail = [string]$persistMatch.Groups['tail'].Value
            $sourceRoot = 'Persist'
        }
    }

    if (-not $sourceRoot) { return $Node }

    $isPersistedPath = $tail -match '^\\(?i:configs|vms|nx_device)(?:\\|$)'
    if ($isPersistedPath) {
        $relative = $tail.TrimStart('\')
        $persistTarget = [IO.Path]::GetFullPath((Join-Path $script:PersistRoot $relative))
        if (-not $persistTarget.StartsWith($script:PersistRoot + '\',[StringComparison]::OrdinalIgnoreCase) -or
            -not (Test-Path -LiteralPath $persistTarget)) {
            $script:Unresolved.Add("$File :: $Node :: expected persisted target $persistTarget")
            return $Node
        }

        if ($script:Phase -eq 'Pre') {
            $newPath = $persistTarget
        } else {
            $versionTarget = [IO.Path]::GetFullPath((Join-Path $script:VersionRoot $relative))
            if (Test-Path -LiteralPath $versionTarget) {
                $newPath = $versionTarget
            } else {
                # The stable persist path remains valid even if Scoop did not
                # create a version-local junction for this specific path.
                $newPath = $persistTarget
            }
        }
    } else {
        $newPath = $script:VersionRoot + $tail
    }

    if (-not $Node.Equals($newPath,[StringComparison]::OrdinalIgnoreCase)) {
        $script:Changed.Add([pscustomobject]@{File=$File;Old=$Node;New=$newPath})
    }
    return $newPath
}

$scanRoots = @(
    (Join-Path $PersistRoot 'configs'),
    (Join-Path $PersistRoot 'nx_device\12.0\configs'),
    (Join-Path $PersistRoot 'nx_device\15.0\configs')
)
$files = [System.Collections.Generic.List[string]]::new()
foreach ($root in $scanRoots) {
    if (Test-Path -LiteralPath $root -PathType Container) {
        Get-ChildItem -LiteralPath $root -Filter '*.json' -File -Recurse -Force |
            ForEach-Object { $files.Add($_.FullName) }
    }
}
if ($AppDataConfig -and (Test-Path -LiteralPath $AppDataConfig -PathType Leaf)) {
    $files.Add([IO.Path]::GetFullPath($AppDataConfig))
}

$plan = [System.Collections.Generic.List[object]]::new()
$fileErrors = [System.Collections.Generic.List[string]]::new()
foreach ($file in @($files | Sort-Object -Unique)) {
    try {
        $raw = Get-Content -LiteralPath $file -Raw -ErrorAction Stop
        $json = ConvertFrom-Json -InputObject $raw -AsHashtable -ErrorAction Stop
        $script:Changed = [System.Collections.Generic.List[object]]::new()
        $script:Unresolved = [System.Collections.Generic.List[string]]::new()
        $json = Set-MuMuPaths -Node $json -File $file

        foreach ($issue in $script:Unresolved) {
            Write-Warning "[MuMu $Phase] Unresolved path: $issue"
        }
        if ($Phase -eq 'Pre' -and $script:Unresolved.Count -gt 0) {
            throw 'A stale persisted path could not be resolved safely.'
        }

        if ($script:Changed.Count -gt 0) {
            $plan.Add([pscustomobject]@{
                File = $file
                After = ConvertTo-Json -InputObject $json -Depth 100
                Changes = @($script:Changed)
            })
        }
    } catch {
        $fileErrors.Add("$file :: $($_.Exception.Message)")
    }
}
if ($fileErrors.Count -gt 0) {
    foreach ($issue in $fileErrors) { Write-Warning "[MuMu $Phase] Config error: $issue" }
    if ($Phase -eq 'Pre') { throw 'MuMu configuration could not be validated; refusing to run the installer.' }
}

if ($plan.Count -gt 0) {
    $backupDir = Join-Path $PersistRoot ("_mumu-scoop-path-backups\" + $Phase + '-' + (Get-Date -Format 'yyyyMMdd-HHmmss-fff'))
    New-Item -ItemType Directory -Path $backupDir -Force | Out-Null
    $done = [System.Collections.Generic.List[object]]::new()
    try {
        $n = 0
        foreach ($item in $plan) {
            $n++
            $backup = Join-Path $backupDir ('{0:D3}-{1}' -f $n,[IO.Path]::GetFileName($item.File))
            $temp = $item.File + '.mumu-' + $PID + '.tmp'
            Copy-Item -LiteralPath $item.File -Destination $backup -Force -ErrorAction Stop
            $done.Add([pscustomobject]@{File=$item.File;Backup=$backup})
            [IO.File]::WriteAllText($temp,$item.After,[Text.UTF8Encoding]::new($false))
            Move-Item -LiteralPath $temp -Destination $item.File -Force -ErrorAction Stop
            Get-Content -LiteralPath $item.File -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop | Out-Null
            foreach ($change in $item.Changes) {
                Write-Host "[MuMu $Phase] $($change.Old) -> $($change.New)"
            }
        }
        $plan | ForEach-Object { $_.File } |
            Set-Content -LiteralPath (Join-Path $backupDir 'files.txt') -Encoding utf8
        Write-Host "[MuMu $Phase] Backups saved: $backupDir"
    } catch {
        foreach ($item in $done) {
            Copy-Item -LiteralPath $item.Backup -Destination $item.File -Force -ErrorAction SilentlyContinue
        }
        throw "Path migration failed; changed JSON files were restored from backup. $($_.Exception.Message)"
    }
} else {
    Write-Host "[MuMu $Phase] No stale Scoop version paths found."
}

if ($Phase -eq 'Post') {
    $engines = @(
        [pscustomobject]@{Version='12.0';Name='Android 12';Runtime='MuMuVMMVbox';Service='MuMuVMMDrv';Driver='MuMuVMMDrv.sys';CLSID='{23cd1535-edaa-4f21-a4ab-45d97fd1d58b}';Server='MuMuVMMSVC.exe'},
        [pscustomobject]@{Version='15.0';Name='Android 15';Runtime='MuMuNxVbox';Service='MuMuNxSup';Driver='MuMuNxSup.sys';CLSID='{50859a2f-a5dd-4fcd-b107-ff2a37b33e4a}';Server='MuMuNxSVC.exe'}
    )
    foreach ($engine in $engines) {
        $engineExe = Join-Path $PersistRoot "nx_device\$($engine.Version)\shell\MuMuNxDevice.exe"
        if (-not (Test-Path -LiteralPath $engineExe -PathType Leaf)) {
            Write-Host "[MuMu Post] $($engine.Name) payload absent; registration check skipped."
            continue
        }

        $runtime = Join-Path $ProgramFilesRoot $engine.Runtime
        $driverFile = Join-Path $runtime "LoadedDrivers\$($engine.Driver)"
        $serverFile = Join-Path $runtime "Hypervisor\$($engine.Server)"
        $issues = [System.Collections.Generic.List[string]]::new()

        if (-not (Test-Path -LiteralPath $driverFile -PathType Leaf)) {
            $issues.Add("Hypervisor driver file missing: $driverFile")
        }
        if (-not (Test-Path -LiteralPath $serverFile -PathType Leaf)) {
            $issues.Add("Hypervisor server missing: $serverFile")
        }

        $servicePath = Join-Path $ServicesRegistryRoot $engine.Service
        $service = Get-ItemProperty -LiteralPath $servicePath -ErrorAction SilentlyContinue
        if (-not $service) {
            $issues.Add("Driver service not registered: $($engine.Service)")
        } else {
            $image = ([string]$service.ImagePath).Trim().Trim('"') -replace '^\\\?\?\\',''
            if (-not (Test-Path -LiteralPath $image -PathType Leaf)) {
                $issues.Add("Registered driver image missing: $image")
            } elseif ([IO.Path]::GetFullPath($image) -ine [IO.Path]::GetFullPath($driverFile)) {
                $issues.Add("Driver service points to unexpected file: $image")
            }
        }

        $comPath = Join-Path $ClassesRegistryRoot ($engine.CLSID + '\LocalServer32')
        $com = Get-Item -LiteralPath $comPath -ErrorAction SilentlyContinue
        $server = if ($com) { ([string]$com.GetValue('')).Trim().Trim('"') } else { '' }
        if (-not $server) {
            $issues.Add("COM LocalServer32 missing: $($engine.CLSID)")
        } elseif ([IO.Path]::GetFullPath($server) -ine [IO.Path]::GetFullPath($serverFile) -or
                  -not (Test-Path -LiteralPath $server -PathType Leaf)) {
            $issues.Add("COM server path is invalid: $server")
        }

        if ($issues.Count -eq 0) {
            Write-Host "[MuMu Post] $($engine.Name): Hypervisor and COM checks passed."
        } else {
            foreach ($issue in $issues) { Write-Warning "[MuMu Post] $($engine.Name): $issue" }
        }
    }
}
Write-Host "[MuMu $Phase] Path migration and validation completed."

'@
    [IO.File]::WriteAllText($mumuMigrationHelperPath, $mumuMigrationHelperContent, [System.Text.UTF8Encoding]::new($false))
    & $mumuMigrationHelperPath -Phase Pre -VersionRoot $dir -PersistRoot $persist_dir -AppDataConfig (Join-Path $env:APPDATA 'Netease\MuMuPlayerGlobal\install_config.json')

    if (Test-Path -LiteralPath $cachedInstaller) {
        $installerPath = $cachedInstaller
        Remove-Item -LiteralPath $sourceInstaller -Force
    } else {
        $scoopRoot = Split-Path (Split-Path (Split-Path $dir -Parent) -Parent) -Parent
        $stagingDir = Join-Path $scoopRoot "cache\mumuplayer-installer-$transactionId"
        New-Item -ItemType Directory -Path $stagingDir -Force | Out-Null
        $installerPath = Join-Path $stagingDir $fname
        Copy-Item -LiteralPath $sourceInstaller -Destination $installerPath -Force
        Remove-Item -LiteralPath $sourceInstaller -Force
    }

    $remainingFiles = @(Get-ChildItem -LiteralPath $dir -Force)
    if ($remainingFiles.Count -gt 0) {
        throw "MuMuPlayer target directory must be empty before setup. Unexpected item: $($remainingFiles[0].FullName)"
    }

    $versionParts = $version -split "\."
    if ($versionParts.Count -lt 3) {
        throw "Cannot derive MuMuPlayer product version from NXMAIN version $version."
    }
    $productVersion = "6.$($versionParts[1]).$($versionParts[2]).0"
    $commonArguments = @(
        "/from_orchestrator=1",
        "/txn_id=$transactionId",
        "/silent=1",
        "/product_version=$productVersion",
        "/auto_start=false",
        "/fchannel=gw-win-download",
        "/auto_run=false",
        "/D=$dir"
    )

    $prepareArguments = @("/from_orchestrator=1", "/action=install_prepare") + $commonArguments[1..($commonArguments.Count - 1)]
    $prepare = Start-Process -FilePath $installerPath -ArgumentList $prepareArguments -Wait -PassThru
    if ($prepare.ExitCode -ne 0) {
        throw "MuMuPlayer NX-main install_prepare failed with exit code $($prepare.ExitCode)."
    }

    Start-Sleep -Seconds 12

    $commitArguments = @("/from_orchestrator=1", "/action=commit") + $commonArguments[1..($commonArguments.Count - 1)]
    $commit = Start-Process -FilePath $installerPath -ArgumentList $commitArguments -Wait -PassThru
    if ($commit.ExitCode -ne 0) {
        throw "MuMuPlayer NX-main commit failed with exit code $($commit.ExitCode)."
    }

    $mainExe = Join-Path $dir "nx_main\MuMuNxMain.exe"
    if (-not (Test-Path $mainExe)) {
        throw "MuMuPlayer setup returned successfully but did not create the expected executable: $mainExe"
    }
    $mumuInstallCompleted = $true
}
finally {
    if (-not $mumuInstallCompleted -and $mumuMigrationHelperPath -and (Test-Path -LiteralPath $mumuMigrationHelperPath)) {
        Remove-Item -LiteralPath $mumuMigrationHelperPath -Force -ErrorAction SilentlyContinue
    }
    if ($stagingDir -and (Test-Path -LiteralPath $stagingDir)) {
        Remove-Item -LiteralPath $stagingDir -Recurse -Force -ErrorAction SilentlyContinue
    }
}
